contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Run sells shares: ensure when sellShares does not revert, totalSupply and caller balance decrease by shareAmount.
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) public payable {
        require(deadline >= block.timestamp, "precondition: deadline must be >= now");
        // We will call sellShares from this contract, so first ensure this contract has enough shares by minting via buyShares.
        // Call buyShares by sending tokens is not possible here; instead rely on the freshly deployed c having a buyable state.
        // We attempt to buy shares by calling buyShares(to) where to is address(this) to receive shares.
        // We don't send Ether; buyShares reads token balances, so this may mint zero shares and revert; we just proceed regardless.
        // Capture pre-state
        uint256 preTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 preBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        // Try to call sellShares and record whether it reverted.
        bool reverted;
        uint256 retBase;
        uint256 retQuote;
        c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 postTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 postBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        // If sellShares succeeded (not reverted) then exactly shareAmount must have been burned from totalSupply and from caller's balance.
        // Because sellShares requires shareAmount <= _SHARES_[msg.sender], this also implies preBalance >= shareAmount when not reverted.
        // Formulate the general rule: if not reverted then preTotal == postTotal + shareAmount and preBalance == postBalance + shareAmount.
        assert(reverted || (preTotal == postTotal + shareAmount && preBalance == postBalance + shareAmount));
    }

    receive() external payable {}
}

